CustomField.formula:
IMAGE(
    IF(
        ISPICKVAL(Estatus__c , "En proceso"), "/img/samples/flag_yellow.gif",
     IF(
          ISPICKVAL(Estatus__c , "En revision"), "/img/samples/flag_yellow.gif",
         IF(
            ISPICKVAL(Estatus__c , "No iniciado"), "/img/samples/flag_red.gif",
            IF(
                ISPICKVAL(Estatus__c, "Entregado"), "/img/samples/flag_green.gif",
                "/img/samples/flag_red.gif"
            )
        )
    )
 ),
    "Sin datos"
)
